{"explanation":"A Riemann sum approximates area by dividing an interval into rectangles and adding their areas. This visualization uses right-endpoint heights for y = x² on [0, 2], and the slider changes how many rectangles are used.","manimCode":"const ax = new Axes({ xRange: [0, 2, 0.5], yRange: [0, 4.5, 1], xLength: 6, yLength: 4.5, tips: true });
const curve = ax.plot(x => x * x, { color: BLUE, xRange: [0, 2], numSamples: 250 });
scene.add(ax, curve);

const title = new Text({ text: 'Right-endpoint Riemann sum for y = x²', color: WHITE, fontSize: 26 });
title.moveTo([0, 3.35, 0]);
scene.add(title);

const sumLabel = new Text({ text: 'n = 4   |   area ≈ 2.750', color: YELLOW, fontSize: 23 });
sumLabel.moveTo([0, -3.15, 0]);
scene.add(sumLabel);

let rectangles = [];
let n = 4;
function rebuildRectangles(count) {
  for (const r of rectangles) scene.remove(r);
  rectangles = [];
  n = count;
  const dx = 2 / n;
  let total = 0;
  for (let i = 1; i <= n; i++) {
    const xRight = i * dx;
    const y = xRight * xRight;
    total += y * dx;
    const p1 = ax.c2p((i - 1) * dx, 0);
    const p2 = ax.c2p(i * dx, y);
    const rect = new Polygon({
      vertices: [p1, ax.c2p(i * dx, 0), p2, ax.c2p((i - 1) * dx, y)],
      color: TEAL
    });
    rect.setFill(TEAL, 0.28).setStrokeWidth(1.5);
    rectangles.push(rect);
    scene.add(rect);
  }
  scene.remove(sumLabel);
  const freshLabel = new Text({ text: `n = ${n}   |   area ≈ ${total.toFixed(3)}`, color: YELLOW, fontSize: 23 });
  freshLabel.moveTo([0, -3.15, 0]);
  sumLabel = freshLabel;
  scene.add(sumLabel);
}

// Rebuild once in the initial state, then let the slider adjust the partition.
rebuildRectangles(4);
const controls = new Controls(scene, { position: 'top-right', width: 250 });
controls.addSlider({ label: 'Rectangles (n)', min: 1, max: 20, value: 4, step: 1, onChange: value => rebuildRectangles(Math.round(value)) });
await scene.wait(999999);"}

